# Reviewed under AGENTS.md
import os
import sys
import tokenize

results = []
for root, dirs, files in os.walk('.'):
    dirs[:] = [d for d in dirs if d != '.git']
    for name in files:
        if not name.endswith('.py'):
            continue
        full = os.path.join(root, name)
        rel = os.path.relpath(full, '.').replace(os.sep, '/')
        try:
            with tokenize.open(full) as f:
                toks = list(tokenize.generate_tokens(f.readline))
        except (tokenize.TokenError, SyntaxError, UnicodeDecodeError, OSError) as e:
            print('skip ' + rel + ': ' + str(e), file=sys.stderr)
            continue
        for tok in toks:
            if tok.type == tokenize.COMMENT and 'TODO' in tok.string:
                results.append((rel, tok.start[0]))

results.sort()
with open('todos.txt', 'w') as out:
    for rel, line in results:
        out.write('%s:%d\n' % (rel, line))
